import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { Refund } from '../../src/entities/refund.entity';
import { buildRefund } from '../factories/refund.factory';
import { Payment } from '../../src/entities/payment.entity';
import { buildPayment } from '../factories/payment.factory';

describe('Refund Relationships', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let paymentId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const paymentEntity = em.create(
      Payment,
      buildPayment(),
    );
    await em.persistAndFlush(paymentEntity);
    paymentId = paymentEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  describe('belongs_to Payment', () => {
    it('persists payment reference', async () => {
      const em = orm.em.fork();
      const data = buildRefund({ payment: paymentId });
      const saved = em.create(Refund, data);
      await em.persistAndFlush(saved);
      await em.populate(saved, ['payment']);
      expect(saved.payment.id).toBe(paymentId);
    });

    it('loads parent via relation', async () => {
      const em = orm.em.fork();
      const data = buildRefund({ payment: paymentId });
      const saved = em.create(Refund, data);
      await em.persistAndFlush(saved);
      const loaded = await em.findOne(
        Refund,
        { id: saved.id },
        { populate: ['payment'] },
      );
      expect(loaded).not.toBeNull();
      expect(loaded!.payment).toBeDefined();
      expect(loaded!.payment.id).toBe(paymentId);
    });

    it('rejects entity without required payment', async () => {
      const em = orm.em.fork();
      const data = buildRefund({ payment: undefined as unknown as string });
      const row = em.create(Refund, data);
      await expect(em.persistAndFlush(row)).rejects.toThrow();
    });
  });
});
